import type { DatabaseSync } from 'node:sqlite';
import { join } from 'node:path';
import { readMigrationFiles, type MigrationMeta } from 'drizzle-orm/migrator';
import { migrate as runMigrations } from 'drizzle-orm/node-sqlite/migrator';
import { projectRoot } from '../config.js';
import { backupPath, migrate as migrateLegacy, schemaVersion } from './legacy.js';
import type { Database } from './store.js';

/** Generated by `pnpm db:generate`; the first folder is the baseline, equal to legacy version 5. */
export const migrationsFolder = join(projectRoot, 'drizzle');

const MIGRATIONS_TABLE = '__drizzle_migrations';

function hasTable(client: DatabaseSync, name: string): boolean {
  return Boolean(
    client.prepare("SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = ?").get(name),
  );
}

/** Names of the Drizzle migrations already applied, which is how Drizzle decides what is pending. */
export function appliedMigrations(client: DatabaseSync): string[] {
  if (!hasTable(client, MIGRATIONS_TABLE)) return [];

  const rows = client.prepare(`SELECT name FROM ${MIGRATIONS_TABLE} ORDER BY id`).all() as {
    name: string | null;
  }[];

  return rows.flatMap((row) => (row.name ? [row.name] : []));
}

/** Records the baseline as applied on a database that already has the legacy version 5 schema. */
function adoptBaseline(client: DatabaseSync, baseline: MigrationMeta): void {
  client.exec('BEGIN IMMEDIATE');

  try {
    // The same table Drizzle's migrator creates, so it recognises the format and appends to it.
    client.exec(`
      CREATE TABLE ${MIGRATIONS_TABLE} (
        id INTEGER PRIMARY KEY, hash text NOT NULL, created_at numeric, name text, applied_at TEXT
      )
    `);
    client
      .prepare(
        `INSERT INTO ${MIGRATIONS_TABLE} (hash, created_at, name, applied_at) VALUES (?, ?, ?, ?)`,
      )
      .run(baseline.hash, baseline.folderMillis, baseline.name, new Date().toISOString());
    client.exec('COMMIT');
  } catch (error) {
    client.exec('ROLLBACK');

    throw error;
  }
}

/**
 * Brings the database up to the latest schema:
 * - a database from before Drizzle finishes the legacy steps to version 5, then adopts the baseline;
 * - an on-disk database with applied migrations is copied with VACUUM INTO before new ones run, so
 *   an upgrade can be undone;
 * - Drizzle then applies whatever is pending, all in one transaction.
 */
export function migrateDatabase(
  db: Database,
  databasePath: string,
  folder = migrationsFolder,
): void {
  const client = db.$client;
  const local = readMigrationFiles({ migrationsFolder: folder });

  if (local.length === 0) throw new Error(`No database migrations found in ${folder}`);

  const legacy =
    !hasTable(client, MIGRATIONS_TABLE) &&
    (schemaVersion(client) > 0 || hasTable(client, 'snapshots'));

  if (legacy) {
    migrateLegacy(client, databasePath);
    adoptBaseline(client, local[0]!);
  }

  const applied = new Set(appliedMigrations(client));
  const pending = local.filter((migration) => !applied.has(migration.name));

  if (pending.length === 0) return;

  if (applied.size > 0 && databasePath !== ':memory:') {
    client.prepare('VACUUM INTO ?').run(backupPath(databasePath, `before-${pending[0]!.name}`));
  }

  runMigrations(db, { migrationsFolder: folder });
}
